begin;set search_path to public,extensions;select plan(29);
insert into auth.users(id,email)values('c0000000-0000-4000-8000-000000000001','operation-owner@example.test'),('c0000000-0000-4000-8000-000000000002','operation-tenant@example.test');
insert into private.administrator_grants(user_id,reason)values('c0000000-0000-4000-8000-000000000001','Synthetic operation administrator');
set local role anon;select is(get_operation_mode()->>'accepts_real_data','false','Intake defaults to demonstration');
select throws_ok($$select configure_operation_mode(true,90,'Synthetic operation mode')$$,'42501',null,'Anonymous mode configuration denied');
select throws_ok($$select operations_health()$$,'42501',null,'Anonymous metrics denied');
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select configure_operation_mode(true,90,'Synthetic operation mode')$$,'42501',null,'Even administrator cannot bypass operator mode boundary');
select throws_ok($$select create_property('{"name":"Synthetic real fixture","address":"Synthetic operation lane","state":"Delhi","city":"Operation city","locality":"Fixture area","type":"Flat","min":1,"max":2,"synthetic":false,"consent":true}',true)$$,'P0001',null,'Real property rejected while intake disabled');
reset role;select configure_operation_mode(true,30,'Synthetic rolled-back operation test');
set local role authenticated;
select throws_ok($$select create_property('{"name":"Synthetic real fixture","address":"Synthetic operation lane","state":"Delhi","city":"Operation city","locality":"Fixture area","type":"Flat","min":1,"max":2,"synthetic":false}',true)$$,'P0001',null,'Real contribution needs consent');
select create_property('{"name":"Synthetic real fixture","address":"Synthetic operation lane","state":"Delhi","city":"Operation city","locality":"Fixture area","type":"Flat","min":1,"max":2,"synthetic":false,"consent":true}',true);
reset role;create temp table operation_property as select id from public.properties where name='Synthetic real fixture';grant select on operation_property to authenticated,service_role;
select is((select is_demo from public.properties where id=(select id from operation_property)),false,'New real property labelled separately');
select is((select is_demo from public.properties where id='20000000-0000-4000-8000-000000000001'),true,'Existing demo label preserved');
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000002',true);
select throws_ok($$select create_review(jsonb_build_object('property',(select id from operation_property),'start','2025-01-01','current',true,'paid',1,'propertyRating',4,'body','Synthetic intake mismatch','synthetic',true))$$,'P0001','Review must match property demonstration status','Demo review cannot enter real profile');
select create_review(jsonb_build_object('property',(select id from operation_property),'start','2025-01-01','current',true,'paid',1,'propertyRating',4,'body','Synthetic real review fixture','synthetic',false,'consent',true));
select is(get_my_reviews()->0->>'is_demo','false','Own review records real status');
reset role;create temp table operation_review as select id from public.reviews where body='Synthetic real review fixture';grant select on operation_review to authenticated,service_role;
insert into storage.objects(bucket_id,name,metadata)values('rental-documents','verification/c2000000-0000-4000-8000-000000000001.pdf','{"mimetype":"application/pdf"}');
set local role service_role;
select throws_ok($$select register_evidence_document('c0000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000001','pdf',(select id from operation_review))$$,'P0001',null,'Cannot classify real evidence as fictional');
select register_evidence_document('c0000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000001','pdf',(select id from operation_review),null,null,false,true);
reset role;create temp table operation_request as select id from private.verification_requests where document_id='c2000000-0000-4000-8000-000000000001';grant select on operation_request to authenticated;
select ok((select expires_at between now()+interval '29 days'and now()+interval '31 days'from private.documents where id='c2000000-0000-4000-8000-000000000001'),'Configured retention applied');
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select decide_verification((select id from operation_request),'approved','Synthetic manual review reason')$$,'P0001',null,'Real approval requires checklist');
select lives_ok($$select decide_verification((select id from operation_request),'approved','Synthetic manual review reason','{"identity":true,"property":true,"period_or_authority":true}')$$,'Complete checklist approval accepted');
select is(get_admin_verifications()->0->>'is_demo','false','Administrator sees explicit real status');
select is(get_review_page((select id from operation_property))->'rows'->0->>'is_demo','false','Public review status explicit');
reset role;update private.documents set expires_at=now()-interval '1 second'where id='c2000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000002',true);
select is(get_authorized_document('c2000000-0000-4000-8000-000000000001'),null::text,'Expired evidence denied before cleanup');
select throws_ok($$select queue_expired_evidence(100)$$,'42501',null,'Ordinary cleanup preparation denied');
set local role service_role;select is(queue_expired_evidence(100),1,'Expired evidence queued');select is(queue_expired_evidence(100),0,'Queue preparation idempotent');
reset role;select is((select object_path from private.documents where id='c2000000-0000-4000-8000-000000000001'),null::text,'Expired path cleared while decision retained');
select ok(exists(select 1 from private.audit_events where action='evidence_checklist'and entity_id=(select id from operation_request)),'Real checklist retained in immutable audit');
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select maintain_association((select id from operation_property),'10000000-0000-4000-8000-000000000001','2020-01-01',null,null,'Synthetic mismatched manager')$$,'P0001','Property and manager must share demonstration status','Demo manager cannot be attached to real property');
select create_manager_profile('Synthetic real manager fixture','Synthetic actual-mode test profile',true,'Synthetic manager source test',false,true);
reset role;create temp table operation_manager as select id from public.landlords where name='Synthetic real manager fixture';grant select on operation_manager to authenticated;
select is((select is_demo from public.landlords where id=(select id from operation_manager)),false,'Real manager has explicit record status');
set local role authenticated;
select lives_ok($$select maintain_association((select id from operation_property),(select id from operation_manager),'2020-01-01',null,null,'Synthetic real management source')$$,'Matching real manager accepted');
reset role;insert into storage.objects(bucket_id,name,metadata)values('rental-documents','claim/c2000000-0000-4000-8000-000000000002.pdf','{"mimetype":"application/pdf"}');
set local role service_role;
select register_evidence_document('c0000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','pdf',null,(select id from operation_property),null,false,true);
set local role authenticated;
select throws_ok($$select decide_claim((get_my_claims()->0->>'id')::uuid,'approved','Synthetic real claimant approval')$$,'P0001',null,'Real claim also requires manual checklist');
select lives_ok($$select decide_claim((get_my_claims()->0->>'id')::uuid,'approved','Synthetic real claimant approval','{"identity":true,"property":true,"period_or_authority":true}')$$,'Complete real claim checklist accepted');
reset role;
delete from auth.users where id='c0000000-0000-4000-8000-000000000002';
select is((select count(*)::int from private.documents where id='c2000000-0000-4000-8000-000000000001'),0,'Account deletion works after evidence expiration');
select ok(exists(select 1 from private.media_purge_queue where object_path='verification/c2000000-0000-4000-8000-000000000001.pdf'),'Physical removal job survives account deletion');
select * from finish();rollback;
